CREATE OR REPLACE FUNCTION public.rpc_take_faith_spell(p_world uuid, p_spell text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); s faith_spell; v_why text; v_slot int;
begin
